INSERT INTO TB_BRODBASICFILE
(
    BASIC_SEQ, BASIC_CODE, ATCH_FILE_ID, USEYN, BASIC_ORDER,
    FRST_REGIST_PNTTM, FRST_REGISTER_ID, LAST_UPDT_PNTTM, LAST_UPDUSR_ID
)
SELECT
    NEXTVAL('basicbrodfile_seq'), #{basicCode}, ATCH_FILE_ID, USEYN, BASIC_ORDER,
    NOW(), #{frstRegisterId,jdbcType=VARCHAR}, NOW(), #{frstRegisterId,jdbcType=VARCHAR}
FROM TB_BRODBASICFILE
WHERE BASIC_CODE = #{basicCodeCp}
